// objects and responses. Source goldens SHA b4d7e063fc9a97bdd356d5817c95cc5df8057e33ca2d78a0022b4543ee7dbd46.
// Original wire SHA 4ddd799944cf8f959430a97294ae0c036e5cb6bc097bc3a57b114e5bcd089130.
// Lookup/file failures and inline authentication are deliberately deferred;
// they are not claimed to have passed complete operation qualification.
use super::*;

#[test]
fn fifty_actual_mcp_samples_keep_errors_and_explicit_deferred_boundaries() {
	let golden: Value = serde_json::from_str(GOLDENS).unwrap();
	let rows = golden["cases"].as_array().unwrap();
	assert_eq!(rows.len(), 50);
	let mut counts = (0, 0, 0);
	for row in rows {
		let name = row["name"].as_str().unwrap();
		let argument_keys: Vec<String> =
			serde_json::from_value(row["argument_keys"].clone()).unwrap();
		let source_keys: Option<Vec<String>> =
			serde_json::from_value(row["source_keys"].clone()).unwrap();
		let view_keys: Option<Vec<String>> =
			serde_json::from_value(row["view_keys"].clone()).unwrap();
		let actual = validate(
			&row["arguments"],
			Some(&argument_keys),
			source_keys.as_deref(),
			view_keys.as_deref(),
		);
		let inline_pending = [
			"inline-evidence-empty",
			"inline-valid-parent",
			"inline-tampered-normalized",
			"inline-tampered-id",
		]
		.contains(&name);
		let external_resolution = [
			"retained-not-found",
			"file-missing",
			"file-exported-bundle-unavailable-id",
		]
		.contains(&name);
		if inline_pending {
			assert_eq!(actual.unwrap(), Validation::InlineEvidencePending, "{name}");
			counts.2 += 1;
		} else if external_resolution || row["value"]["isError"] != true {
			assert_eq!(actual.unwrap(), Validation::Supported, "{name}");
			counts.1 += 1;
		} else {
			let error = actual.unwrap_err();
			assert_eq!(
				error.0, row["value"]["content"][0]["text"]["error"],
				"{name}: full original input error differs"
			);
			counts.0 += 1;
		}
	}
	assert_eq!(counts, (35, 11, 4));
}

#[test]
fn all_other_published_kinds_are_capability_gaps_never_schema_success() {
	let mut gaps = 0;
	for kind in VIEW_KINDS {
		if ["summary", "apk-signature"].contains(kind) {
			continue;
		}
		let input = json!({"source":{"kind":"retained-evidence","evidence_id":format!("ev_{}", "0".repeat(64))},
            "view":{"kind":kind}});
		assert_eq!(
			validate(&input, None, None, None).unwrap(),
			Validation::CapabilityGap {
				kind: kind.to_string()
			}
		);
		gaps += 1;
	}
	assert_eq!(gaps, 37);
}

#[test]
fn incomplete_or_duplicate_order_hints_never_authorize_properties() {
	let input = json!({"source":{"kind":"retained-evidence","evidence_id":format!("ev_{}", "0".repeat(64)), "a":1,"z":2},
        "view":{"kind":"summary","a":1,"z":2},"a":1,"z":2});
	let hint = vec!["z".to_owned(), "z".to_owned()];
	let error = validate(&input, Some(&hint), Some(&hint), Some(&hint)).unwrap_err();
	let paths: Vec<_> = error.0["details"]["issues"]
		.as_array()
		.unwrap()
		.iter()
		.map(|i| i["path"].clone())
		.collect();
	assert_eq!(
		paths,
		vec![
			json!(["source", "z"]),
			json!(["source", "a"]),
			json!(["view", "z"]),
			json!(["view", "a"]),
			json!(["z"]),
			json!(["a"])
		]
	);
}

